mapper.select:
SELECT COUNT(*)
FROM REVIEW
WHERE MEMBER_NO = #{memberNo}

SELECT COUNT(*)
FROM REVIEW
WHERE ORDER_DETAIL_NO = #{orderDetailNo}

mapper.delete:
DELETE FROM REVIEW_IMAGE ri
WHERE ri.REVIEW_NO = #{reviewNo}
  AND EXISTS (
      SELECT 1
      FROM REVIEW r
      WHERE r.REVIEW_NO = ri.REVIEW_NO
        AND r.MEMBER_NO = #{memberNo}
  )

DELETE FROM REVIEW
WHERE REVIEW_NO = #{reviewNo}
  AND MEMBER_NO = #{memberNo}

mapper.update:
UPDATE REVIEW
   SET PRODUCT_RATING = #{review.productRating},
       SERVICE_RATING = #{review.serviceRating},
       REVIEW_CONTENT = #{review.reviewContent},
       REVIEW_SUMMARY = #{review.reviewSummary}
 WHERE REVIEW_NO = #{review.reviewNo}
   AND MEMBER_NO = #{memberNo}
